// Parse Z-API webhook (formato 'Ao receber'). Identifica origem (operador x lead) e ação.
const body = $input.item.json.body || $input.item.json;

if (body.fromMe === true || body.isGroup === true || body.type !== 'ReceivedCallback') {
  return { json: { skip: true, reason: 'fromMe/group/notReceived' } };
}

const fromNumber = String(body.phone || '').replace(/\D/g, '');
const contactName = body.senderName || body.chatName || null;
const messageText = body.text?.message || body.image?.caption || body.audio?.caption || '';
const messageId = body.messageId;

if (!fromNumber || !messageText) {
  return { json: { skip: true, reason: 'noNumberOrText' } };
}

const operatorNumber = String($('Config').first().json.operatorNumber).replace(/\D/g, '');
const isFromOperator = fromNumber === operatorNumber;

let command = null;
let commandPayload = null;
if (isFromOperator) {
  const trimmed = messageText.trim();
  const upper = trimmed.toUpperCase();
  if (upper === 'APROVAR' || upper === 'APROVA' || upper === 'OK' || upper === '✅') {
    command = 'approve';
  } else if (upper === 'PULAR' || upper === 'PULA' || upper === 'SKIP' || upper === '❌') {
    command = 'skip';
  } else if (upper.startsWith('EDITAR:') || upper.startsWith('EDITAR ')) {
    command = 'edit';
    commandPayload = trimmed.replace(/^EDITAR[:\s]+/i, '').trim();
  } else {
    return { json: { skip: true, reason: 'operatorFreeText' } };
  }
}

const route = isFromOperator ? command : 'lead_reply';

return {
  json: { skip: false, fromNumber, contactName, messageText, messageId, isFromOperator, command, commandPayload, route }
};

const lead = $input.item.json;
if (!lead || !lead.id) {
  return { json: { error: 'NoPendingLead', msg: 'Nenhum lead em Aguardando aprovação' } };
}
const props = lead.property || lead.properties || {};
const getText = (key) => {
  const p = props[key];
  if (!p) return '';
  if (p.title) return p.title.map(t => t.plain_text).join('');
  if (p.rich_text) return p.rich_text.map(t => t.plain_text).join('');
  if (p.phone_number) return p.phone_number;
  return '';
};
const whatsapp = getText('WhatsApp').replace(/\D/g, '');
const mensagem = getText('Mensagem proposta');
const nome = getText('Nome');
const empresa = getText('Empresa');
const historicoExistente = getText('Histórico');
const now = new Date().toISOString().replace('T', ' ').slice(0, 16);
const novaLinha = `[${now} SDR] ${mensagem}`;
const historicoAtualizado = historicoExistente ? `${historicoExistente}\n${novaLinha}` : novaLinha;
return { json: { lead_id: lead.id, whatsapp, mensagem, nome, empresa, historicoAtualizado } };

