const lead = $input.item.json;
const inbound = $('Parse Z-API + identifica').item.json;
if (!lead || !lead.id) {
  return { json: { isNewLead: true, fromNumber: inbound.fromNumber, contactName: inbound.contactName, messageText: inbound.messageText } };
}
const props = lead.property || lead.properties || {};
const getText = (key) => {
  const p = props[key];
  if (!p) return '';
  if (p.title) return p.title.map(t => t.plain_text).join('');
  if (p.rich_text) return p.rich_text.map(t => t.plain_text).join('');
  if (p.select) return p.select?.name || '';
  if (p.phone_number) return p.phone_number;
  if (p.url) return p.url;
  return '';
};
const historicoExistente = getText('Histórico');
const now = new Date().toISOString().replace('T', ' ').slice(0, 16);
const novaLinha = `[${now} LEAD] ${inbound.messageText}`;
const historicoAtualizado = historicoExistente ? `${historicoExistente}\n${novaLinha}` : novaLinha;
return { json: {
  isNewLead: false,
  lead_id: lead.id,
  nome: getText('Nome'),
  empresa: getText('Empresa'),
  cargo: getText('Cargo'),
  whatsapp: getText('WhatsApp'),
  gatilho: getText('Gatilho de prospecção'),
  setor: getText('Setor'),
  instagram: getText('Instagram'),
  site: getText('Site da empresa'),
  ultima_msg_lead: inbound.messageText,
  historico: historicoAtualizado,
  is_first_touch: false
} };

