const claudeResp = $input.item.json;
const ctx = $('Monta contexto + histórico').item.json;
let parsed;
try {
  const text = claudeResp.content[0].text.trim();
  const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { mensagem_proposta: '[ERRO de parsing — revisar]', raciocinio: 'Falha no parsing: ' + e.message, score_sugerido: '🟡 Warm', proxima_etapa_sugerida: 'Em conversa', alerta_humano: 'Claude retornou JSON inválido em follow-up' };
}
return { json: { ...ctx, ...parsed } };
